-- Synthetic test accounts only. Plaintext passwords.
-- Standalone fixture based on RegisteredPlayer; not an ORMLite-generated dump.
BEGIN TRANSACTION;
CREATE TABLE AUTH (
 NICKNAME VARCHAR(255) NOT NULL,
 LOWERCASENICKNAME VARCHAR(255) PRIMARY KEY,
 HASH VARCHAR(255) NOT NULL,
 IP VARCHAR(255), TOTPTOKEN VARCHAR(255), REGDATE BIGINT,
 UUID VARCHAR(255), PREMIUMUUID VARCHAR(255), LOGINIP VARCHAR(255),
 LOGINDATE BIGINT, ISSUEDTIME BIGINT
);
CREATE INDEX AUTH_IP_idx ON AUTH(IP);
CREATE INDEX AUTH_PREMIUMUUID_idx ON AUTH(PREMIUMUUID);
